import{_ as e,o as t,c as r,a4 as l}from"./chunks/framework.9tZL7ZIQ.js";const u=JSON.parse('{"title":"艾略特·塔特尔曼","description":"","frontmatter":{"title":"艾略特·塔特尔曼","date":"2026-04-13T00:00:00.000Z"},"headers":[],"relativePath":"04_people/艾略特·塔特尔曼.md","filePath":"04_people/艾略特·塔特尔曼.md"}'),o={name:"04_people/艾略特·塔特尔曼.md"};function i(n,a,s,_,d,h){return t(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="艾略特·塔特尔曼" tabindex="-1">艾略特·塔特尔曼 <a class="header-anchor" href="#艾略特·塔特尔曼" aria-label="Permalink to &quot;艾略特·塔特尔曼&quot;">​</a></h1><ul><li><strong>角色职位</strong>：乔丹家具（Jordan Furniture）高管</li><li><strong>与巴菲特关系</strong>：被伯克希尔·哈撒韦收购的子公司管理层成员</li></ul><h2 id="主要事迹" tabindex="-1">主要事迹 <a class="header-anchor" href="#主要事迹" aria-label="Permalink to &quot;主要事迹&quot;">​</a></h2><p>艾略特·塔特尔曼是乔丹家具（Jordan Furniture）的高管，与创始人巴里·塔特尔曼共同参与公司的经营管理工作。乔丹家具是新英格兰地区历史悠久的家具零售商，以其本地化的服务理念和稳定的产品质量在区域内赢得了良好口碑。艾略特作为管理层核心成员，在公司的日常运营和战略决策中扮演重要角色。</p><p>在乔丹家具被伯克希尔·哈撒韦收购的过程中，艾略特·塔特尔曼与其他管理层成员共同确保了收购过渡的顺利完成。伯克希尔在收购企业后通常保持原有管理层的完整性和独立运营权限，艾略特在公司中的持续参与正是这一策略的体现。他的存在有助于维护乔丹家具原有的企业文化和服务标准，确保顾客体验不会因股权变动而受到影响。</p><p>艾略特·塔特尔曼的管理工作涵盖了乔丹家具的多个业务层面，从门店运营到供应链管理均有参与。这种全面性的管理经验，使得乔丹家具在被伯克希尔收购后仍能保持较强的市场竞争力。伯克希尔旗下拥有多家家具零售企业，乔丹家具能够在其中保持独立特色，离不开艾略特等管理层的持续贡献。</p><h2 id="关键年份事件" tabindex="-1">关键年份事件 <a class="header-anchor" href="#关键年份事件" aria-label="Permalink to &quot;关键年份事件&quot;">​</a></h2><ul><li><strong>高管任期</strong>：作为乔丹家具核心管理层，主导公司日常运营管理</li><li><strong>收购过渡期</strong>：在伯克希尔收购乔丹家具期间，与创始人团队共同推进平稳过渡</li><li><strong>后续运营期</strong>：在伯克希尔控股下继续管理乔丹家具，维护品牌在新英格兰地区的影响力</li></ul><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该人物在致股东信中被提及的关键年份，点击即可阅读完整翻译：</p><ul><li><a href="/search.html?q=艾略特·塔特尔曼在1999年股东信中的原话">1999年：完整翻译|/01_letters/1999年/翻译</a></li></ul>',11)])])}const c=e(o,[["render",i]]);export{u as __pageData,c as default};
